## Casos de uso principales

### 1. Métodos de utilidad (no necesitan estado de instancia)

```javascript
class Validador {
  static esEmail(valor) {
    return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(valor);
  }

  static esURL(valor) {
    try { new URL(valor); return true; }
    catch { return false; }
  }

  static esNumeroPositivo(valor) {
    return typeof valor === 'number' && valor > 0;
  }
}

console.log(Validador.esEmail('ana@ejemplo.com')); // true
console.log(Validador.esEmail('no-es-email'));      // false
```

### 2. Factory methods (alternativas al constructor)

```javascript
class Fecha {
  constructor(dia, mes, anio) {
    this.dia = dia;
    this.mes = mes;
    this.anio = anio;
  }

  // Factory methods — formas alternativas de crear instancias
  static hoy() {
    const d = new Date();
    return new Fecha(d.getDate(), d.getMonth() + 1, d.getFullYear());
  }

  static desdeString(str) {
    const [dia, mes, anio] = str.split('/').map(Number);
    return new Fecha(dia, mes, anio);
  }

  toString() {
    return `${this.dia}/${this.mes}/${this.anio}`;
  }
}

const hoy = Fecha.hoy();
const navidad = Fecha.desdeString('25/12/2026');
console.log(String(navidad)); // '25/12/2026'
```

### 3. Contador de instancias

```javascript
class Conexion {
  static _total = 0;
  static get total() { return Conexion._total; }

  constructor(url) {
    this.url = url;
    Conexion._total++;
  }

  cerrar() {
    Conexion._total--;
  }
}

const c1 = new Conexion('db://localhost');
const c2 = new Conexion('db://server');
console.log(Conexion.total); // 2
c1.cerrar();
console.log(Conexion.total); // 1
```

