class Moneda {
  static #tasas = { USD: 1, EUR: 0.92, COP: 4000 };

  static convertir(cantidad, de, a) {
    const enUSD = cantidad / Moneda.#tasas[de];
    return Number((enUSD * Moneda.#tasas[a]).toFixed(2));
  }

  static agregarMoneda(codigo, tasaEnUSD) {
    Moneda.#tasas[codigo] = tasaEnUSD;
  }

  static monedas() {
    return Object.keys(Moneda.#tasas);
  }
}

console.log(Moneda.convertir(100, 'USD', 'EUR')); // 92
console.log(Moneda.convertir(1, 'USD', 'COP'));   // 4000
console.log(Moneda.monedas()); // ['USD', 'EUR', 'COP']

class ID {
  static #siguiente = 1;

  static generar() {
    return ID.#siguiente++;
  }

  static resetear() {
    ID.#siguiente = 1;
  }
}

class Tarea {
  constructor(titulo) {
    this.id = ID.generar();
    this.titulo = titulo;
    this.completada = false;
  }

  completar() {
    this.completada = true;
    return this;
  }
}

const t1 = new Tarea('Estudiar prototipos');
const t2 = new Tarea('Practicar clases');
const t3 = new Tarea('Hacer ejercicios');

console.log(t1.id, t2.id, t3.id); // 1, 2, 3

